// npm run local:smoke
// Quick NON-CLOUD end-to-end check of the three local engines using SYNTHETIC speech generated by
// the Mac's own TTS. This verifies plumbing and timing. It is NOT an adult-speech verification
// (L02/L03 need a real adult speaking into the iPhone) and says so in its output.
import { performance } from 'node:perf_hooks';
import { errorCodeOf, type NormalizedUsage, type RequestMeta } from '@kt/shared';
import { loadConfig, loadDotenv } from '../src/config';
import { createLocalProvider } from '../src/providers/local';

loadDotenv();
const { local: cfg } = loadConfig();
const provider = createLocalProvider(cfg);
const health = await provider.refresh(true);
if (!health.ready) {
  console.log(`SKIPPED: local engines are not ready (${health.status}). Run \`npm run local:doctor\`.`);
  process.exit(2);
}

let failures = 0;
const usageLog: NormalizedUsage[] = [];
const meta = (n: string): RequestMeta => ({ taskId: `smoke-${n}`, requestId: `smoke-${n}`, report: (u) => usageLog.push(u) });
async function step<T>(name: string, fn: () => Promise<T>, check: (v: T) => string | null): Promise<T | null> {
  const t = performance.now();
  try {
    const v = await fn();
    const problem = check(v);
    const ms = Math.round(performance.now() - t);
    if (problem) {
      failures++;
      console.log(`FAIL ${name.padEnd(28)} ${ms}ms  ${problem}`);
    } else console.log(`ok   ${name.padEnd(28)} ${ms}ms`);
    return v;
  } catch (e) {
    failures++;
    console.log(`FAIL ${name.padEnd(28)} ${errorCodeOf(e)}`);
    return null;
  }
}
const has = (text: string, ...needles: string[]) => (needles.some((n) => text.toLowerCase().includes(n.toLowerCase())) ? null : `unexpected result: "${text}"`);

console.log(`Local smoke - ${provider.describe().modelTag}\n(synthetic speech from macOS say; not an adult-speech test)\n`);

const zhText = '我想去厕所。';
const svText = 'Jag vill gå på toaletten.';
const zhAudio = await step('TTS zh (generate input)', () => provider.tts.synthesize(zhText, 'zh', meta('tts-zh')), (a) => (a.bytes.length > 1000 ? null : 'audio too short'));
const svAudio = await step('TTS sv (generate input)', () => provider.tts.synthesize(svText, 'sv', meta('tts-sv')), (a) => (a.bytes.length > 1000 ? null : 'audio too short'));

if (zhAudio) await step('ASR zh (synthetic speech)', () => provider.asr.transcribe(zhAudio, 'zh', meta('asr-zh')), (t) => has(t, '厕所'));
if (svAudio) await step('ASR sv (synthetic speech)', () => provider.asr.transcribe(svAudio, 'sv', meta('asr-sv')), (t) => has(t, 'toalett'));

await step('LLM interpret zh (clear)', () => provider.dialogue.interpretChinese({ dialogueInputs: [{ purpose: 'INITIAL', textParts: [zhText] }], remainingClarifications: 3 }, meta('int')), (r) => (r.kind === 'PROPOSE_MEANING' ? null : `kind=${r.kind}`));
const toSv = await step('LLM translate zh->sv', () => provider.dialogue.translate({ text: zhText, direction: 'ZH_TO_SV' }, meta('t1')), (t) => has(t, 'toalett'));
const toZh = await step('LLM translate sv->zh', () => provider.dialogue.translate({ text: svText, direction: 'SV_TO_ZH' }, meta('t2')), (t) => has(t, '厕所', '洗手间'));

if (toSv) await step('TTS sv (result)', () => provider.tts.synthesize(toSv, 'sv', meta('r-sv')), (a) => (a.mimeType === 'audio/wav' && (a.durationMs ?? 0) > 300 ? null : 'not a playable WAV'));
if (toZh) await step('TTS zh (result)', () => provider.tts.synthesize(toZh, 'zh', meta('r-zh')), (a) => (a.mimeType === 'audio/wav' && (a.durationMs ?? 0) > 300 ? null : 'not a playable WAV'));

const loads = usageLog.map((u) => u.modelLoadMs).filter((v): v is number => v !== undefined);
console.log(`\nOllama model load reported: ${loads.map((l) => `${Math.round(l)}ms`).join(', ') || 'n/a'}`);
console.log(failures === 0 ? '\nPASS (plumbing, synthetic speech only).' : `\n${failures} step(s) FAILED.`);
process.exit(failures === 0 ? 0 : 1);
